if (p.type !== "message" || typeof p.content !== "string" || !p.content.trim()) {
    return null;
}
// O único lugar com configuração de conexão
msg.cfg = {
    baseUrl: env.get("ASSISTANTS_BASE_URL"),
    apiKey: env.get("ASSISTANTS_API_KEY"),
    assistantId: env.get("BOOKKEEPER_ASSISTANT_ID")
};
const from = (msg.originalMessage && msg.originalMessage.from) || {};
msg.chatId = p.chatId;
msg.text = p.content.trim();
const name = [from.first_name, from.last_name].filter(Boolean).join(" ") || from.username || null;
msg.params = [from.id || p.chatId, name];
return msg;

