while (msg.callIndex < msg.calls.length) {
    const call = msg.calls[msg.callIndex];
    if (call.function.name === "get_books") {
        let args = {};
        try { args = JSON.parse(call.function.arguments || "{}"); } catch (e) { args = {}; }
        msg.params = [String(args.category || "")];
        return [msg, null];
    }
    msg.outputs.push({ tool_call_id: call.id, output: "Unknown tool '" + call.function.name + "'." });
    msg.callIndex++;
}
return [null, request(msg, "POST", "/threads/" + msg.threadId + "/runs/" + msg.runId + "/submit_tool_outputs",
    { tool_outputs: msg.outputs })];

